// #1ccd9e / #55dc54 — серверная защита (RLS Supabase): запросы REST от имени роли, мимо интерфейса.
// Кейсы: .qa/tests/permissions-isolation/PI-05, PI-06, PI-09..PI-12.
// Безопасность: только чтение и попытки записи, которые сервер обязан отклонить. DELETE не используется.
// PATCH чужих компании/тендера пишет ТО ЖЕ значение, что уже есть (даже при дыре данные не меняются).
// Повышение роли USER — настоящая попытка (role=admin); при дыре роль сразу возвращается сессией admin.
// INSERT при дыре создал бы строку — тест упадёт с пометкой «удалить вручную» (DELETE в тестах запрещён).
// @data — идёт отдельно, по одному: тест обращается к данным общих аккаунтов.
import { test, expect } from '../../fixtures';
import { sbSession, sbSelect, sbPatch, sbInsert, myCompanyId } from '../helpers/supabase';
import { TENDERS_A } from './test-data';

test.describe('הרשאות בשרת — משתמש רגיל', () => {
  test('משתמש רגיל לא יכול לשנות את סוג ההרשאה שלו בשרת (0 שורות) #1ccd9e @desktop @data', async ({ asUser }) => {
    const user = await sbSession(await asUser('user'));
    const before = await sbSelect<{ role: string }>(user, `company_members?select=role&user_id=eq.${user.userId}`);
    expect(before).toEqual([{ role: 'member' }]);

    const res = await sbPatch(user, `company_members?user_id=eq.${user.userId}`, { role: 'admin' });
    const body = await res.text();
    if (res.ok() && body !== '[]') {
      // Дыра: вернуть роль сразу, затем упасть.
      const admin = await sbSession(await asUser('admin'));
      await sbPatch(admin, `company_members?user_id=eq.${user.userId}`, { role: 'member' });
      throw new Error(`БАГ: USER повысил себе роль (ответ ${body}); роль возвращена на member`);
    }
    expect(res.status(), body).toBe(200);
    expect(body, 'изменённых строк быть не должно').toBe('[]');

    const after = await sbSelect<{ role: string }>(user, `company_members?select=role&user_id=eq.${user.userId}`);
    expect(after).toEqual([{ role: 'member' }]);
  });

  test('משתמש רגיל לא יכול ליצור הזמנה בשרת (403) #1ccd9e @desktop @data', async ({ asUser }) => {
    const user = await sbSession(await asUser('user'));
    const companyA = await myCompanyId(user);
    const email = `qa-auto-invite-user-${Date.now()}@example.com`;
    const res = await sbInsert(user, 'company_invitations', {
      company_id: companyA,
      email,
      full_name: 'QA-AUTO user invite',
      role: 'member',
    });
    const body = await res.text();
    expect(res.status(), `ожидался отказ RLS 403; при 2xx — БАГ, удалить приглашение ${email} вручную. Ответ: ${body}`).toBe(403);
  });
});

test.describe('הפרדת נתונים בשרת — חברה B מול חברה A', () => {
  test('מנהל חברה B לא יכול לשנות את חברה A (0 שורות) #55dc54 @desktop @data', async ({ asUser }) => {
    const admin = await sbSession(await asUser('admin'));
    const admin2 = await sbSession(await asUser('admin2'));
    const companyA = await myCompanyId(admin);
    expect(companyA).not.toBe(await myCompanyId(admin2));
    const [{ name }] = await sbSelect<{ name: string }>(admin, `companies?select=name&id=eq.${companyA}`);

    // B не видит компанию A и при чтении.
    expect(await sbSelect(admin2, `companies?select=id&id=eq.${companyA}`)).toEqual([]);

    const res = await sbPatch(admin2, `companies?id=eq.${companyA}`, { name });
    const body = await res.text();
    expect(res.status(), body).toBe(200);
    expect(body, 'изменённых строк быть не должно').toBe('[]');
    expect(await sbSelect(admin, `companies?select=name&id=eq.${companyA}`)).toEqual([{ name }]);
  });

  test('מנהל חברה B לא יכול לשנות מכרז של חברה A (0 שורות) #55dc54 @desktop @data', async ({ asUser }) => {
    const admin = await sbSession(await asUser('admin'));
    const admin2 = await sbSession(await asUser('admin2'));
    const id = TENDERS_A.byAdmin1;
    const [{ title }] = await sbSelect<{ title: string }>(admin, `tenders?select=title&id=eq.${id}`);

    expect(await sbSelect(admin2, `tenders?select=id&id=eq.${id}`)).toEqual([]);

    const res = await sbPatch(admin2, `tenders?id=eq.${id}`, { title });
    const body = await res.text();
    expect(res.status(), body).toBe(200);
    expect(body, 'изменённых строк быть не должно').toBe('[]');
    expect(await sbSelect(admin, `tenders?select=title&id=eq.${id}`)).toEqual([{ title }]);
  });

  test('מנהל חברה B לא יכול להצטרף לחברה A בשרת (403) #55dc54 @desktop @data', async ({ asUser }) => {
    const admin = await sbSession(await asUser('admin'));
    const admin2 = await sbSession(await asUser('admin2'));
    const companyA = await myCompanyId(admin);
    const res = await sbInsert(admin2, 'company_members', { company_id: companyA, user_id: admin2.userId, role: 'member' });
    const body = await res.text();
    expect(res.status(), `ожидался отказ RLS 403; при 2xx — БАГ, удалить строку company_members (admin2 в компании A) вручную. Ответ: ${body}`).toBe(403);
    // admin2 по-прежнему только в своей компании.
    await myCompanyId(admin2);
  });

  test('מנהל חברה B לא יכול ליצור הזמנה לחברה A בשרת (403) #55dc54 @desktop @data', async ({ asUser }) => {
    const admin = await sbSession(await asUser('admin'));
    const admin2 = await sbSession(await asUser('admin2'));
    const companyA = await myCompanyId(admin);
    const email = `qa-auto-invite-b-${Date.now()}@example.com`;
    const res = await sbInsert(admin2, 'company_invitations', {
      company_id: companyA,
      email,
      full_name: 'QA-AUTO cross-company invite',
      role: 'member',
    });
    const body = await res.text();
    expect(res.status(), `ожидался отказ RLS 403; при 2xx — БАГ, удалить приглашение ${email} вручную. Ответ: ${body}`).toBe(403);
    // Приглашения не появилось у компании A.
    expect(await sbSelect(admin, `company_invitations?select=id&email=eq.${encodeURIComponent(email)}`)).toEqual([]);
  });
});
